import {createDiagnosticPanel,diagnosticHidden} from './diagnostic.mjs';
import {createTrends} from './trends.mjs';
import {sensorTags} from './hmi-model.mjs';
export function createHMI({host,onApply,onCommand,onFault,onProcessFault,onAck,onRearm,trace,onPlay,onScan,onDiagnosticStart,onDiagnosticExit,onRefresh,onDiagnosticRepair,onInspect}){
 const root=document.createElement('section');root.className='hmi';root.setAttribute('aria-label','Pantalla HMI conectada al PLC');
 root.innerHTML=`<header><span class="eyebrow">HMI / BANCO NEUMÁTICO · DATOS DEL PLC</span><h2>Supervisar. Ajustar. Diagnosticar.</h2><span id="hmiStatus"></span></header><div class="hmi-grid"><section><h3>Proceso en vivo</h3><div id="hmiPositions"></div><p>Posición del modelo simulado. Los sensores digitales solo indican los extremos.</p><div id="hmiInputs"></div><p id="hmiBatch"></p><div class="hmi-actions"><button id="hmiStart">Marcha</button><button id="hmiStop">Paro</button></div></section><form id="hmiRecipe"><h3>Ajustes del lote</h3><div class="hmi-fields">${['AP','BP','BM','AM'].map((k,i)=>`<label>T${i+1} · ${['A+','B+','B−','A−'][i]} (s)<input name="${k}" type="number" min="0" max="5" step="0.1" value="1" required></label>`).join('')}<label>Ciclos · PV<input name="target" type="number" min="1" max="50" step="1" value="5" required></label></div><button type="submit">Aplicar al PLC</button><p>Con RUN=0. Para cambiar PV, reinicia primero C1. Aplicar no arranca ni borra el contador.</p><p id="hmiWrite" role="status"></p></form><section><h3>Alarmas y diagnóstico</h3><div id="hmiAlarms" aria-live="polite"></div><div class="hmi-actions"><button id="hmiAck">Reconocer</button><button id="hmiRearm">Rearmar PLC</button><button id="hmiReset">Reiniciar C1</button></div><div class="hmi-actions"><button id="hmilowPressure" aria-pressed="false">Presión baja</button><button id="hmijamA" aria-pressed="false">Atascar A</button><button id="hmijamB" aria-pressed="false">Atascar B</button></div><p id="hmiPressure"></p><p>Presión nominal 4 bar; presostato PS / I0.4 válido desde 3 bar. La prueba de pérdida total fija 0 bar y congela el movimiento ideal. Un atasco inmoviliza solo el cilindro elegido. En automático, la falta de llegada dispara el timeout; en manual observa la posición, sin supervisión de carrera.</p><details><summary>Simular fallo de sensor</summary><label>Señal <select id="hmiSensor">${Object.entries(sensorTags).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><button id="hmiDisconnect">Desconectar</button><p>Desconectar fuerza la entrada a 0. El PLC detecta falta de confirmación por timeout en automático, no identifica físicamente un cable roto.</p></details></section></div>`;
 host.before(root);const diagnostic=createDiagnosticPanel(root,{onStart:onDiagnosticStart,onExit:onDiagnosticExit,onRefresh,onRepair:onDiagnosticRepair,onInspect});for(const key of ['lowPressure','jamA','jamB'])root.querySelector('#hmi'+key).onclick=()=>onProcessFault(key);const trends=createTrends(root,{trace,onPlay,onScan,onDiagnosticStart,onDiagnosticExit,onRefresh,onDiagnosticRepair,onInspect});const form=root.querySelector('form');let dirty=false,lastRecipe='',lastAlarm='';form.addEventListener('input',()=>dirty=true);form.onsubmit=e=>{e.preventDefault();const result=onApply({target:form.elements.target.value,delays:Object.fromEntries(['AP','BP','BM','AM'].map(k=>[k,form.elements[k].value]))});root.querySelector('#hmiWrite').textContent=result.message;if(result.ok){dirty=false;lastRecipe='';}};
 for(const [id,command]of [['hmiStart','start'],['hmiStop','stop'],['hmiReset','resetCount']])root.querySelector('#'+id).onclick=()=>onCommand(command);root.querySelector('#hmiAck').onclick=onAck;root.querySelector('#hmiRearm').onclick=onRearm;root.querySelector('#hmiDisconnect').onclick=()=>onFault(root.querySelector('#hmiSensor').value);root.querySelector('#hmiSensor').onchange=()=>root.dispatchEvent(new Event('hmi-select'));
 return {update(s,disabled,playing){diagnostic.update(s,disabled);const hidden=diagnosticHidden(s),challenge=!!s.diagnostic;trends.update(s,playing,disabled);for(const id of ['hmilowPressure','hmijamA','hmijamB','hmiDisconnect','hmiSensor'])root.querySelector('#'+id).hidden=hidden;const q=id=>root.querySelector('#'+id);for(const [key,label]of [['lowPressure','Presión baja'],['jamA','Atasco A'],['jamB','Atasco B']]){q('hmi'+key).textContent=s[key]?'Restaurar · '+label:label;q('hmi'+key).setAttribute('aria-pressed',String(s[key]));q('hmi'+key).disabled=disabled||challenge;}q('hmiPressure').textContent=s.pressure.toFixed(2)+' bar · PS / I0.4='+Number(s.pressureOK)+(hidden?'':' · Atasco A='+Number(s.jamA)+' / B='+Number(s.jamB));q('hmiStatus').textContent=(s.fault?'ALARMA':s.complete?'LOTE COMPLETO':s.run?'EN MARCHA':'DETENIDO')+' · '+s.mode.toUpperCase();q('hmiStatus').dataset.alarm=s.fault;
 q('hmiPositions').innerHTML=[['A',s.x,s.q],['B',s.y,s.qB]].map(([tag,x,v])=>`<div class="hmi-position"><strong>${tag}</strong><progress value="${x*100}" max="100" aria-label="Posición ${tag}"></progress><output>${(x*100).toFixed(1)} mm</output><small>Y${tag}=${Number(v)}</small></div>`).join('');q('hmiInputs').innerHTML=Object.entries(sensorTags).map(([key,tag])=>`<span class="${s[key]?'on':''}">${tag} <b>${Number(s[key])}</b></span>`).join('');q('hmiBatch').textContent='C1: '+s.cycles+' / '+s.target+' ciclos · scan '+s.time.toFixed(2)+' s';
 const recipe=JSON.stringify([s.delays,s.target]);if(!dirty&&recipe!==lastRecipe){for(const k of ['AP','BP','BM','AM'])form.elements[k].value=s.delays[k];form.elements.target.value=s.target;lastRecipe=recipe;}for(const element of form.elements)element.disabled=s.run||s.fault||disabled||challenge;
 q('hmiStart').disabled=disabled||s.run||s.fault||(s.mode==='auto'&&s.complete);q('hmiStop').disabled=disabled;q('hmiReset').disabled=disabled||s.run||s.fault||!s.i0||!s.i2;q('hmiRearm').disabled=challenge||disabled||s.lowPressure||s.jamA||s.jamB||!s.fault||!s.i0||!s.i2||s.alarms.some(a=>a.active&&s.disabledSensors[a.sensor]);q('hmiAck').disabled=disabled||!s.alarms.some(a=>!a.ack);
 const warning=Object.entries(hidden?{}:s.disabledSensors).filter(([,v])=>v).map(([k])=>sensorTags[k]);const alarms=JSON.stringify([s.alarms,warning,s.i0,s.i2,s.run,s.mode]);if(alarms!==lastAlarm){lastAlarm=alarms;q('hmiAlarms').innerHTML=(warning.length?'<p class="hmi-warning">Prueba activa: '+warning.join(', ')+' desconectado.</p>':'')+(!s.run&&s.mode==='auto'&&(!s.i0||!s.i2)?'<p class="hmi-warning">Marcha inhibida: falta confirmación de origen.</p>':'')+(s.alarms.length?s.alarms.map(a=>`<article class="hmi-alarm ${a.active?'active':''}"><b>${a.code} · ${a.tag}</b><p>${a.message}</p><small>${a.time.toFixed(2)} s · ${a.active?'ACTIVA':'RESUELTA'} · ${a.ack?'reconocida':'sin reconocer'}</small></article>`).join(''):'<p>Sin alarmas registradas.</p>');}
 const key=q('hmiSensor').value;q('hmiDisconnect').textContent=s.disabledSensors[key]?'Reconectar':'Desconectar';q('hmiDisconnect').disabled=disabled||challenge;
 }};
}
